CREATE TYPE public.studio_role AS ENUM ('admin');
CREATE TABLE public.studio_user_roles (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.studio_role NOT NULL, PRIMARY KEY (user_id, role));
GRANT SELECT ON public.studio_user_roles TO authenticated;
GRANT ALL ON public.studio_user_roles TO service_role;
ALTER TABLE public.studio_user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.studio_user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.studio_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.studio_user_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.studio_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.studio_is_admin() TO anon, authenticated, service_role;
CREATE TABLE public.studio_procedures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) > 0), description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK (price_cents >= 0), duration_minutes integer NOT NULL CHECK (duration_minutes > 0), image_url text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.studio_procedures TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.studio_procedures TO authenticated;
GRANT ALL ON public.studio_procedures TO service_role;
ALTER TABLE public.studio_procedures ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_active_procedures ON public.studio_procedures FOR SELECT TO anon, authenticated USING (active);
CREATE POLICY admin_procedures ON public.studio_procedures FOR ALL TO authenticated USING (public.studio_is_admin()) WITH CHECK (public.studio_is_admin());
CREATE TABLE public.studio_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) > 0), phone text NOT NULL, birthday date, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.studio_clients TO authenticated;
GRANT ALL ON public.studio_clients TO service_role;
ALTER TABLE public.studio_clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_clients ON public.studio_clients FOR ALL TO authenticated USING (public.studio_is_admin()) WITH CHECK (public.studio_is_admin());
CREATE TABLE public.studio_appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.studio_clients(id) ON DELETE RESTRICT, procedure_id uuid NOT NULL REFERENCES public.studio_procedures(id) ON DELETE RESTRICT, starts_at timestamptz NOT NULL, duration_minutes integer NOT NULL CHECK (duration_minutes > 0), price_cents integer NOT NULL CHECK (price_cents >= 0), status text NOT NULL DEFAULT 'Pendente' CHECK (status IN ('Pendente','Confirmado','Atendido','Não atendido','Cancelado')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.studio_appointments TO authenticated;
GRANT ALL ON public.studio_appointments TO service_role;
ALTER TABLE public.studio_appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_appointments ON public.studio_appointments FOR ALL TO authenticated USING (public.studio_is_admin()) WITH CHECK (public.studio_is_admin());
CREATE INDEX studio_appointments_date_idx ON public.studio_appointments(starts_at);
CREATE TABLE public.studio_financial_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid REFERENCES public.studio_appointments(id) ON DELETE RESTRICT, kind text NOT NULL CHECK (kind IN ('entrada','despesa')), description text NOT NULL CHECK (length(trim(description)) > 0), amount_cents integer NOT NULL CHECK (amount_cents > 0), payment_method text NOT NULL CHECK (payment_method IN ('Pix','Dinheiro','Débito','Crédito')), occurred_on date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.studio_financial_entries TO authenticated;
GRANT ALL ON public.studio_financial_entries TO service_role;
ALTER TABLE public.studio_financial_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_finances ON public.studio_financial_entries FOR ALL TO authenticated USING (public.studio_is_admin()) WITH CHECK (public.studio_is_admin());
CREATE INDEX studio_finance_date_idx ON public.studio_financial_entries(occurred_on);
CREATE UNIQUE INDEX studio_appointment_income_once ON public.studio_financial_entries(appointment_id) WHERE kind = 'entrada' AND appointment_id IS NOT NULL;
CREATE FUNCTION public.studio_validate_appointment() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
DECLARE procedure_row public.studio_procedures;
BEGIN
 PERFORM pg_advisory_xact_lock(4815162342);
 SELECT * INTO procedure_row FROM public.studio_procedures WHERE id=NEW.procedure_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Procedimento não encontrado'; END IF;
 IF TG_OP='INSERT' OR NEW.procedure_id IS DISTINCT FROM OLD.procedure_id THEN
  IF NOT procedure_row.active THEN RAISE EXCEPTION 'Procedimento inativo'; END IF;
  NEW.price_cents := procedure_row.price_cents;
  NEW.duration_minutes := procedure_row.duration_minutes;
 END IF;
 IF NEW.status NOT IN ('Cancelado','Não atendido') AND EXISTS (SELECT 1 FROM public.studio_appointments a WHERE a.id<>NEW.id AND a.status NOT IN ('Cancelado','Não atendido') AND a.starts_at < NEW.starts_at + make_interval(mins=>NEW.duration_minutes) AND NEW.starts_at < a.starts_at + make_interval(mins=>a.duration_minutes)) THEN RAISE EXCEPTION 'Horário em conflito'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER studio_appointment_validation BEFORE INSERT OR UPDATE ON public.studio_appointments FOR EACH ROW EXECUTE FUNCTION public.studio_validate_appointment();
CREATE FUNCTION public.studio_financial_summary(_from date, _to date) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('income_cents',coalesce(sum(amount_cents) FILTER (WHERE kind='entrada'),0),'expense_cents',coalesce(sum(amount_cents) FILTER (WHERE kind='despesa'),0),'balance_cents',coalesce(sum(CASE WHEN kind='entrada' THEN amount_cents ELSE -amount_cents END),0)) FROM public.studio_financial_entries WHERE occurred_on BETWEEN _from AND _to $$;
REVOKE ALL ON FUNCTION public.studio_financial_summary(date,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.studio_financial_summary(date,date) TO authenticated, service_role;